import{bV as n,aL as a,u as s,G as d}from"./chunks/framework.DT-LCgF3.js";const c=JSON.parse('{"title":"RAG 完整链路与架构选型（2）全链路总览","description":"","frontmatter":{"date":"2026-11-25T14:00:00.000Z","title":"RAG 完整链路与架构选型（2）全链路总览","permalink":"/pages/rag02","categories":["AI","RAG"]},"headers":[],"relativePath":"AI/02.RAG/完整链路与架构选型/02.全链路总览.md","filePath":"AI/02.RAG/完整链路与架构选型/02.全链路总览.md","lastUpdated":1795655557000}'),r={name:"AI/02.RAG/完整链路与架构选型/02.全链路总览.md"};function e(p,t,l,o,i,h){return a(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="rag-完整链路与架构选型-2-全链路总览" tabindex="-1">RAG 完整链路与架构选型（2）全链路总览 <a class="header-anchor" href="#rag-完整链路与架构选型-2-全链路总览" aria-label="Permalink to &quot;RAG 完整链路与架构选型（2）全链路总览&quot;">​</a></h1><h2 id="二、全链路总览" tabindex="-1">二、全链路总览 <a class="header-anchor" href="#二、全链路总览" aria-label="Permalink to &quot;二、全链路总览&quot;">​</a></h2><h3 id="_2-1-两段式架构" tabindex="-1">2.1 两段式架构 <a class="header-anchor" href="#_2-1-两段式架构" aria-label="Permalink to &quot;2.1 两段式架构&quot;">​</a></h3><p>RAG 的完整链路分成<strong>两段</strong>，它们的触发时机、性能要求、优化目标都不同。分清这一点是后续所有设计决策的前提。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【离线索引链路】建库时执行一次；文档变更时对受影响部分重跑</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  原始文档    →   解析清洗    →   切分    →   向量化    →   写入索引</span></span>
<span class="line"><span>  PDF / HTML      抽取纯文本      Chunk       Embedding     向量库</span></span>
<span class="line"><span>  Markdown        去噪、去重      父子块       批处理        倒排索引（稀疏路）</span></span>
<span class="line"><span>  数据库          统一格式        加元数据     归一化        元数据字段</span></span>
<span class="line"><span>                                                            （含权限、时间、来源）</span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>【在线查询链路】每次提问执行；有明确的延迟预算</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  用户提问  →  查询理解  →  召回  →  重排  →  生成  →  答案</span></span>
<span class="line"><span>              改写          多路并行   交叉编码器   Prompt     带引用</span></span>
<span class="line"><span>              分解          稀疏+稠密  精排        约束</span></span>
<span class="line"><span>              指代消解      融合(RRF)  Top-N       引用校验</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><strong>两段的关键差异：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>离线索引链路</th><th>在线查询链路</th></tr></thead><tbody><tr><td>触发时机</td><td>建库时 / 文档更新时</td><td>每次用户提问</td></tr><tr><td>性能要求</td><td>吞吐优先，可容忍分钟级到小时级</td><td>延迟优先，通常要求秒级返回</td></tr><tr><td>失败代价</td><td>可重跑，影响面是数据新鲜度</td><td>用户直接感知，影响体验</td></tr><tr><td>优化目标</td><td>索引质量、更新成本</td><td>延迟、精度、成本三者平衡</td></tr><tr><td>常见瓶颈</td><td>解析质量、切分粒度、批量向量化耗时</td><td>向量检索、重排推理、生成 token 消耗</td></tr></tbody></table><p>一句话概括：<strong>离线链路的产出质量决定了在线链路的上限</strong>。切分粒度不对、解析丢了三线表、元数据没带权限字段——这些问题在后面任何一个环节都补不回来。这是本文把切分单独讲一节的（3.2）原因。</p><h3 id="_2-2-各环节的产出与常见实现" tabindex="-1">2.2 各环节的产出与常见实现 <a class="header-anchor" href="#_2-2-各环节的产出与常见实现" aria-label="Permalink to &quot;2.2 各环节的产出与常见实现&quot;">​</a></h3><table tabindex="0"><thead><tr><th>环节</th><th>输入</th><th>产出</th><th>关键决策</th><th>常见实现</th></tr></thead><tbody><tr><td>解析清洗</td><td>原始文件</td><td>纯文本 + 结构信息</td><td>表格/代码怎么保留</td><td>各类文档解析库、专用解析服务</td></tr><tr><td>切分</td><td>纯文本</td><td>Chunk 列表</td><td>粒度、是否重叠、父子关系</td><td>递归字符切分、语义切分、结构感知切分</td></tr><tr><td>向量化</td><td>Chunk 文本</td><td>稠密向量 + 稀疏权重</td><td>模型选型、维度、归一化</td><td>各类 Embedding 模型</td></tr><tr><td>索引构建</td><td>向量 + 原文 + 元数据</td><td>可检索索引</td><td>索引算法与参数</td><td>HNSW / IVF / DiskANN、倒排索引</td></tr><tr><td>查询理解</td><td>用户原始问题</td><td>规范化查询</td><td>是否需要改写、分解</td><td>查询改写、指代消解、HyDE</td></tr><tr><td>召回</td><td>查询</td><td>Top-K1 候选</td><td>单路还是多路、怎么融合</td><td>BM25 + 向量检索 + RRF</td></tr><tr><td>重排</td><td>K1 个候选</td><td>Top-K2 精选片段</td><td>用不用重排、用哪种</td><td>Cross-Encoder / 迟交互 / LLM 打分</td></tr><tr><td>生成</td><td>K3 个片段 + 问题</td><td>最终答案</td><td>上下文怎么组织、怎么约束</td><td>Prompt 工程、引用校验</td></tr></tbody></table><h3 id="_2-3-质量杠杆与成本杠杆" tabindex="-1">2.3 质量杠杆与成本杠杆 <a class="header-anchor" href="#_2-3-质量杠杆与成本杠杆" aria-label="Permalink to &quot;2.3 质量杠杆与成本杠杆&quot;">​</a></h3><p>工程资源有限，要知道力气该往哪使。按<strong>投入产出比</strong>排序，实践中通常的优先级如下（<strong>这是经验判断，不是实测结论</strong>，你的数据分布不同可能顺序不同）：</p><p><strong>质量杠杆（按通常收益从高到低）</strong></p><ol><li><strong>切分策略</strong> —— 影响最大且最容易被忽视。切错了，后面所有环节都在为错误的输入做优化。</li><li><strong>混合检索</strong> —— 向量检索与关键词检索的失效模式高度互补，多路召回通常比单路有明显提升。</li><li><strong>重排</strong> —— 在召回候选已包含正确文档的前提下，重排能显著改善送入生成模型的片段质量。注意前提：<strong>重排不可能修复召回阶段没捞回来的文档</strong>。</li><li><strong>查询改写</strong> —— 对口语化提问、多轮对话场景收益明显；对已规范的短查询收益有限。</li><li><strong>生成侧 Prompt 约束</strong> —— 影响的是&quot;有依据但答偏&quot;和&quot;无依据硬答&quot;这两类问题，对检索本身无能为力。</li></ol><p><strong>成本杠杆（按通常消耗从高到低）</strong></p><ol><li><strong>生成模型的 token 消耗</strong> —— 通常是整条链路最大的持续性成本，且与 K3 和片段长度成正比。</li><li><strong>重排模型的推理算力</strong> —— 若自托管，需要 GPU 且成本与 K1、序列长度成正比。</li><li><strong>向量库的内存占用</strong> —— 向量本体 + ANN 图结构常驻内存，规模上去后是硬成本。</li><li><strong>向量化的批量计算</strong> —— 一次性或增量成本，通常可接受。</li></ol><p>一个务实的结论：<strong>先在低成本的环节上把质量做够</strong>（切分、混合检索），再考虑引入重排这类需要额外算力的组件。顺序反了，容易花了大成本却收效甚微。</p><h3 id="_2-4-建议的推进顺序" tabindex="-1">2.4 建议的推进顺序 <a class="header-anchor" href="#_2-4-建议的推进顺序" aria-label="Permalink to &quot;2.4 建议的推进顺序&quot;">​</a></h3><p>不要一上来就把所有组件都堆上。分阶段推进，每一阶段都能独立上线并产生价值：</p><table tabindex="0"><thead><tr><th>阶段</th><th>做什么</th><th>验证目标</th></tr></thead><tbody><tr><td>第一阶段</td><td>解析 + 切分 + 单路向量检索 + 生成，配最简 Prompt</td><td>链路能跑通，答案基本可用</td></tr><tr><td>第二阶段</td><td>加混合检索（补一路关键词检索并融合）</td><td>专有名词、编号类查询的召回明显改善</td></tr><tr><td>第三阶段</td><td>加重排，确定 K1/K2/K3</td><td>送入生成模型的片段质量提升，答案准确率提升</td></tr><tr><td>第四阶段</td><td>建离线评估集，做参数寻优；加引用校验与拒答</td><td>效果可量化、可回归，减少胡编</td></tr><tr><td>第五阶段</td><td>按需引入查询改写、上下文压缩、权限过滤等增强</td><td>针对性解决已定位的问题</td></tr></tbody></table><p>每一阶段都应先建立<strong>可测量的评估手段</strong>（见第九章），否则无法判断改动是变好还是变坏——很多时候，凭直觉的&quot;优化&quot;实际是负收益。</p><hr><blockquote><p>接下来的章节按链路顺序展开：第三章讲离线链路，第四章到第六章分别深入召回、重排、生成，第七章和第八章讲模型与架构选型，第九章讲评估，第十章给出落地路径。</p></blockquote>`,23)])])}const g=n(r,[["render",e]]);export{c as __pageData,g as default};
